3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Single source of truth for the owner-household identity rule. Two owners count as the same
12	 * household when their last names match and their addresses match, each compared case-insensitively
13	 * with surrounding and repeated whitespace collapsed. This class owns both the comparison
14	 * ({@link #sameHousehold}, built on {@link #normalize}) and the derivation of the stable shared
15	 * {@link #householdId} that identifies a household.
16	 *
17	 * <p>Used by {@link CheckOwnerHouseholdUnique} to reject a non-opted-in duplicate, and by
18	 * {@link AssignOwnerHousehold} to find the household's existing members and to compute the id they
19	 * share — so the definition of "same household" lives here and nowhere else.
20	 */
21	final class OwnerHousehold {
22	
23	    private OwnerHousehold() {
24	    }
25	
26	    /**
27	     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
28	     * single space, and lower-cased. A {@code null} value yields an empty string.
29	     */
30	    static String normalize(String value) {
31	        if (value == null) {
32	            return "";
33	        }
34	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
35	    }
36	
37	    /**
38	     * Tells whether an existing owner belongs to the household identified by the given last name and
39	     * address — the one place that defines what "same household" means. Both sides are reduced
40	     * through {@link #normalize} before comparison, so differently cased or spaced values that mean
41	     * the same thing still match.
42	     */
43	    static boolean sameHousehold(Owner existing, String lastName, String address) {
44	        return normalize(existing.getLastName()).equals(normalize(lastName))
45	                && normalize(existing.getAddress()).equals(normalize(address));
46	    }
47	
48	    /**
49	     * Derives the stable household identifier shared by every owner in the same household. Two
50	     * owners whose normalized last name and address match produce the same value, so the id can be
51	     * computed independently for each joining owner without coordinating through the database. The
52	     * value is {@code "HH-"} followed by the first 12 upper-case hex characters of the SHA-256 of
53	     * the normalized {@code "<lastName>|<address>"}.
54	     */
55	    static String householdId(String lastName, String address) {
56	        String key = normalize(lastName) + "|" + normalize(address);
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest(key.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder();
61	            for (int i = 0; i < 6; i++) {
62	                sb.append(String.format("%02X", digest[i]));
63	            }
64	            return "HH-" + sb;
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException("SHA-256 not available", ex);
68	        }
69	    }
70	}
