8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create request that is missing or blank in any required owner field.
12	 *
13	 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
14	 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
15	 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
16	 * are collected and reported together via {@link OwnerFieldsInvalidException}.
17	 *
18	 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
19	 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
20	 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
21	 */
22	public class ValidateOwnerFields {
23	
24	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
25	            throws OwnerFieldsInvalidException {
26	        List<String> errors = new ArrayList<>();
27	        if (isBlank(request.getFirstName())) {
28	            errors.add("firstName");
29	        }
30	        if (isBlank(request.getLastName())) {
31	            errors.add("lastName");
32	        }
33	        if (isBlank(request.getAddress())) {
34	            errors.add("address");
35	        }
36	        if (isBlank(request.getCity())) {
37	            errors.add("city");
38	        }
39	        if (isBlank(request.getTelephone())) {
40	            errors.add("telephone");
41	        }
42	        else {
43	            String telephone = OwnerTelephone.toE164(request.getTelephone());
44	            if (telephone == null) {
45	                errors.add("telephone");
46	            }
47	            else {
48	                request.setTelephone(telephone);
49	            }
50	        }
51	        // Email is optional. When present it must be syntactically valid; it is normalized to
52	        // lower case so it is stored and returned lower-cased.
53	        String email = request.getEmail();
54	        if (email != null) {
55	            if (!OwnerEmail.isValid(email)) {
56	                errors.add("email");
57	            }
58	            else {
59	                request.setEmail(OwnerEmail.normalize(email));
60	            }
61	        }
62	        if (!errors.isEmpty()) {
63	            throw new OwnerFieldsInvalidException(errors);
64	        }
65	        validated.set(request);
66	    }
67	
68	    private static boolean isBlank(String value) {
69	        return value == null || value.isBlank();
70	    }
71	}
